vec2 p2xy(vec2 p) {
    vec2 r = iResolution.xy;
    vec2 s = r.x > r.y ? r.yy : r.xx;
    return (p/r*2. - 1.) * r/s;
}

vec3 color(float t) {
    return vec3(t, t*t*0.4, t*t*t*0.15);
}

void mainImage(out vec4 o, vec2 p) {
    vec2 q = p2xy(p);
    float sr = 6000.; // 6 kHz

    // 48000 Hz of audio = 60 Hz of video
    // 48000/60 = 800 audio samples per video frame
    int n = int(sr * iTimeDelta);
    int t = int(sr * iTime);

    vec2[2] src = vec2[](vec2(-1,0), vec2(1,0));
    if (iMouse.z > 0.) src[0] = p2xy(iMouse.xy);

    vec2 a = vec2(1e6, -1e6);

    for (int j = 0; j < min(n, 150); j++) {
        float sum = 0.;

        for (int i = 0; i < src.length(); i++) {
            int d = int(length(q - src[i]) * iResolution.x * 0.5);
            vec2 s = guitarSound(max(t - d - j, 0), sr);
            sum += s.x;
        }

        a.x = min(a.x, sum);
        a.y = max(a.y, sum);
    }

    o.rgb = color(2.5*(a.y - a.x));
    o.a = 1.;
}

vec2 mainSound(int samp, float time) {
    return guitarSound(samp, iSampleRate);
}

